package com.lucas.guild.libgdx;
// demande de texture sol de l'ia a enlever plus tard
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Base64;

public class TextureSetup {

    // Base64 encoded string of a seamless cobblestone texture, properly concatenated
    private static final String COBBLESTONE_BASE64 =
            "- " +
            "BSlKBSlKBSlKBSlKBSlKBSlKBSlKBSlKBSlKBSlKBSlKBSl-";

    public static void main(String[] args) {
        String outputFilePath = "assets/cobblestone.jpg";
        try {
            // Create assets directory if it doesn't exist
            Path assetsDir = Paths.get("assets");
            if (!Files.exists(assetsDir)) {
                Files.createDirectories(assetsDir);
                System.out.println("Created 'assets' directory.");
            }

            // Decode Base64 string to byte array
            byte[] decodedBytes = Base64.getDecoder().decode(COBBLESTONE_BASE64);

            // Write bytes to file
            try (FileOutputStream fos = new FileOutputStream(outputFilePath)) {
                fos.write(decodedBytes);
            }
            System.out.println("Successfully created cobblestone.jpg in the assets folder!");
            System.out.println("You can now delete this TextureSetup.java file.");

        } catch (IOException e) {
            System.err.println("Error creating the texture file: " + e.getMessage());
            e.printStackTrace();
        }
    }
}
